import Foundation
import CryptoKit

// OAuth Configuration for CLI upload tool
struct OAuthConfig {
    static let clientId = "cli-upload-tool-v2"
    static let allowedSchemes = ["https"]
    static let allowedHosts = ["auth.example.com", "login.example.com"]
    static let callbackPath = "/oauth/callback"
    static let stateLength = 32
}

// Represents an uploaded file with metadata
struct UploadManifest: Codable {
    let filename: String
    let checksum: String
    let redirectAfterAuth: String?
    let metadata: [String: String]?
}

// URL validation result
enum URLValidationResult {
    case valid(URL)
    case invalid(String)
}

// Normalize URL by resolving percent-encoding and removing fragments
func normalizeURL(_ urlString: String) -> String {
    // Single-pass decode only - no iterative decoding to prevent bypass
    let normalized = urlString.removingPercentEncoding ?? urlString
    return normalized
}

// Validate redirect URI against allowed origins
func validateRedirectURI(_ rawURI: String) -> URLValidationResult {
    let normalized = normalizeURL(rawURI)

    guard let url = URL(string: normalized) else {
        return .invalid("Malformed URL")
    }

    // Check scheme
    guard let scheme = url.scheme?.lowercased(),
          OAuthConfig.allowedSchemes.contains(scheme) else {
        return .invalid("Invalid scheme - only HTTPS allowed")
    }

    // Check host against allowlist - exact match only, no subdomain wildcarding
    guard let host = url.host?.lowercased() else {
        return .invalid("Missing host")
    }

    let hostValid = OAuthConfig.allowedHosts.contains(where: { allowedHost in
        return host == allowedHost
    })

    guard hostValid else {
        return .invalid("Host not in allowlist: \(host)")
    }

    return .valid(url)
}

// Generate cryptographic state parameter
func generateState() -> String {
    var bytes = [UInt8](repeating: 0, count: OAuthConfig.stateLength)
    let status = SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes)
    guard status == errSecSuccess else {
        // Fall back to CryptoKit's secure random if SecRandomCopyBytes is unavailable
        let key = SymmetricKey(size: .init(bitCount: OAuthConfig.stateLength * 8))
        return key.withUnsafeBytes { Data($0).base64EncodedString() }
    }
    return Data(bytes).base64EncodedString()
}

// Build the OAuth authorization URL
func buildAuthorizationURL(redirectURI: URL, state: String) -> URL? {
    var components = URLComponents()
    components.scheme = "https"
    components.host = "auth.example.com"
    components.path = "/authorize"
    components.queryItems = [
        URLQueryItem(name: "client_id", value: OAuthConfig.clientId),
        URLQueryItem(name: "redirect_uri", value: redirectURI.absoluteString),
        URLQueryItem(name: "response_type", value: "code"),
        URLQueryItem(name: "state", value: state),
        URLQueryItem(name: "scope", value: "upload:write")
    ]
    return components.url
}

// Process an upload manifest from untrusted input
func processUploadManifest(jsonData: Data) -> Result<URL, Error> {
    do {
        let decoder = JSONDecoder()
        let manifest = try decoder.decode(UploadManifest.self, from: jsonData)

        // Validate filename
        guard !manifest.filename.contains("..") && !manifest.filename.contains("/") else {
            return .failure(NSError(domain: "Upload", code: 400, userInfo: [NSLocalizedDescriptionKey: "Invalid filename"]))
        }

        // Determine redirect URI
        let redirectString: String
        if let customRedirect = manifest.redirectAfterAuth {
            redirectString = customRedirect
        } else {
            redirectString = "https://auth.example.com/oauth/callback"
        }

        // Validate the redirect URI
        switch validateRedirectURI(redirectString) {
        case .valid(let validatedURL):
            let state = generateState()
            guard let authURL = buildAuthorizationURL(redirectURI: validatedURL, state: state) else {
                return .failure(NSError(domain: "OAuth", code: 500, userInfo: [NSLocalizedDescriptionKey: "Failed to build auth URL"]))
            }
            return .success(authURL)

        case .invalid(let reason):
            return .failure(NSError(domain: "OAuth", code: 403, userInfo: [NSLocalizedDescriptionKey: "Redirect validation failed: \(reason)"]))
        }
    } catch {
        return .failure(error)
    }
}

// Main entry point
func main() {
    let args = CommandLine.arguments
    guard args.count > 1 else {
        print("Usage: upload-tool <manifest.json>")
        return
    }

    let filePath = args[1]
    guard let data = FileManager.default.contents(atPath: filePath) else {
        print("Error: Cannot read file at \(filePath)")
        return
    }

    switch processUploadManifest(jsonData: data) {
    case .success(let authURL):
        print("Open this URL to authorize: \(authURL.absoluteString)")
    case .failure(let error):
        print("Error: \(error.localizedDescription)")
    }
}

main()
